void point2ScreenQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float2 quadPositionUV[32], 
    float2 placement, 
 inout TriangleStream<geometryInS> outStream  ) 
{ 
    geometryInS outS  = inputs[0]; 
    float2 sizeIn = pointSz  / screenSize;  
    outS.Pc = inputs[0].Pc / inputs[0].Pc.w; 
    float2 pos = outS.Pc.xy; 
    if (outS.Pc.z > 0.0) {    
      int iv = int(floor(inputs[0].SymbolChartIndex.x + 0.5)); 
      [unroll] for( int i = 0; i < 4; ++i ) { 
           outS.Pc.xy = pos.xy + sizeIn * (quadPositionUV[i] + placement); 
			outS.SymbolChartIndex = quadPositionUV[4 + i + 4*iv]; 
           outStream.Append( outS ); 
	   } 
    } 
}


void point2ScreenQuad( AttribArray<geometryInS>inputs, float2 pointSz, float2 screenSize, float2 quadPositionUV[32], 
   float2 placement) 
{ 
    geometryInS outS  = inputs[0]; 
    float2 sizeIn = pointSz  / screenSize;  
    outS.Pc = inputs[0].Pc / inputs[0].Pc.w; 
    float2 pos = outS.Pc.xy; 
    if (outS.Pc.z > -1.0) {    
      int iv = int(floor(inputs[0].SymbolChartIndex.x + 0.5)); 
      for( int i = 0; i < 4; ++i ) { 
          outS.Pc.xy = pos + sizeIn * (quadPositionUV[i] + placement); 
		   outS.SymbolChartIndex = quadPositionUV[4 + i + 4*iv]; 
          emitVertex( outS ); 
      } 
    } 
}


void point2ScreenQuad(  vec2 pointSz, vec2 screenSize, vec2 quadPositionUV[32], 
   vec2 placement) 
{ 
    GEO_OUT_struct outS  = copyFromGEO_IN(0); 
    vec2 sizeIn = pointSz  / screenSize;  
    outS.Pc = gl_in[0].gl_Position / gl_in[0].gl_Position.w; 
    vec2 pos = outS.Pc.xy; 
    if (outS.Pc.z > -1.0) {    
      int iv = int(floor(GEO_IN[0].SymbolChartIndex.x + 0.5)); 
      for( int i = 0; i < 4; ++i ) { 
          outS.Pc.xy = pos + sizeIn * (quadPositionUV[i] + placement); 
		   outS.SymbolChartIndex = quadPositionUV[4 + i + 4*iv]; 
          EmitGeoStruct( outS ); 
      } 
    } 
}


void point2ScreenQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float2 quadPositionUV[32], 
    float2 placement, 
 inout TriangleStream<geometryInS> outStream  ) 
{ 
    geometryInS outS  = inputs[0]; 
    float2 sizeIn = pointSz  / screenSize;  
    outS.Pc = inputs[0].Pc / inputs[0].Pc.w; 
    float2 pos = outS.Pc.xy; 
    if (outS.Pc.z > 0.0) {    
      int iv = int(floor(inputs[0].SymbolChartIndex.x + 0.5)); 
      [unroll] for( int i = 0; i < 4; ++i ) { 
           outS.Pc.xy = pos.xy + sizeIn * (quadPositionUV[i] + placement); 
			outS.SymbolChartIndex = quadPositionUV[4 + i + 4*iv]; 
           outStream.Append( outS ); 
	   } 
    } 
}
